Here's a practical pattern for AI-driven security remediation with human approval gates:

```python
import json
from datetime import datetime

class AIRemediationWorkflow:
    def __init__(self, finding, ai_model, approval_threshold="high"):
        self.finding = finding
        self.ai_model = ai_model
        self.approval_threshold = approval_threshold

    def ai_triage(self):
        """Step 1: AI analyzes and prioritizes the finding"""
        prompt = f"""
        Analyze this cloud security finding and provide:
        1. Risk level (Critical/High/Medium/Low)
        2. Likely attack scenario
        3. Recommended remediation (specific CLI commands)
        4. Confidence score (0-1)

        Finding: {json.dumps(self.finding, indent=2)}
        """
        analysis = self.ai_model.analyze(prompt)
        return analysis

    def ai_remediate(self, analysis):
        """Step 2: Generate remediation actions"""
        if analysis['confidence'] < 0.7:
            return {
                "action": "flag_for_human_review",
                "reason": f"Low confidence: {analysis['confidence']}"
            }

        if analysis['risk_level'] in ['Critical', 'High']:
            return {
                "action": "request_human_approval",
                "remediation": analysis['recommended_remediation'],
                "reason": f"{analysis['risk_level']} risk requires human approval"
            }

        # Medium/Low risk + high confidence = auto-remediate
        return {
            "action": "auto_remediate",
            "remediation": analysis['recommended_remediation']
        }

    def execute(self):
        """Step 3: Execute with appropriate approval level"""
        analysis = self.ai_triage()
        action = self.ai_remediate(analysis)

        if action['action'] == 'auto_remediate':
            return self._apply_remediation(action['remediation'])
        elif action['action'] == 'request_human_approval':
            return self._request_approval(analysis, action)
        else:
            return self._flag_for_review(analysis)
```

**Key principle:** Low-risk + high-confidence = auto-remediate. High-risk or low-confidence = human approval required.
